/* base.js */
/* Ядро плагина «ИИ»: чистый JS для потока плагина, наружу — объект AI; сеть — функцией приложения «запрос». */
const AI = {product: 'Пульс Офис', appTitle: 'Puls Office', site: '', timeout: 180000};
{
const enc = new TextEncoder(), A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/', R = new Int16Array(128).fill(-1);
for (let i = 0; i < 64; i++) R[A.charCodeAt(i)] = i;
AI.utf8 = s => enc.encode(String(s ?? ''));
AI.unutf8 = b => new TextDecoder().decode(b);
AI.bytes = x => ArrayBuffer.isView(x) ? new Uint8Array(x.buffer, x.byteOffset, x.byteLength)
  : Object.prototype.toString.call(x) === '[object ArrayBuffer]' ? new Uint8Array(x) : AI.utf8(x);
AI.concat = parts => { const o = new Uint8Array(parts.reduce((a, p) => a + p.length, 0)); let k = 0; for (const p of parts) { o.set(p, k); k += p.length } return o };
AI.b64 = x => {
  const b = AI.bytes(x), out = []; let s = '';
  for (let i = 0; i < b.length; i += 3) {
    const n = b[i] << 16 | (b[i + 1] ?? 0) << 8 | (b[i + 2] ?? 0);
    s += A[n >> 18] + A[n >> 12 & 63] + (i + 1 < b.length ? A[n >> 6 & 63] : '=') + (i + 2 < b.length ? A[n & 63] : '=');
    if (s.length > 8192) { out.push(s); s = '' }
  }
  return out.join('') + s;
};
AI.unb64 = s => {
  const o = new Uint8Array(s.length * 3 >> 2); let n = 0, bits = 0, k = 0;
  for (let i = 0; i < s.length; i++) { const v = R[s.charCodeAt(i)] ?? -1; if (v < 0) continue; n = n << 6 | v; bits += 6; if (bits >= 8) o[k++] = n >> (bits -= 8) & 255 }
  return o.subarray(0, k);
};
AI.dataUrl = u => {
  const m = /^data:([^;,]*)((?:;[^;,]*)*),([\s\S]*)$/.exec(u || '');
  return m && {mime: m[1] || 'application/octet-stream', data: /;base64/i.test(m[2]) ? m[3].replace(/\s+/g, '') : AI.b64(decodeURIComponent(m[3]))};
};
AI.toDataUrl = (b, mime) => `data:${mime};base64,${AI.b64(b)}`;
AI.fail = (kind, message, code, extra) => Object.assign(new Error(message), {kind, code}, extra);
AI.aborted = () => AI.fail('abort', 'Остановлено.');
AI.clip = (s, n, what = 'Текст') => (s = String(s ?? '')).length <= n ? s : s.slice(0, n) + `\n…[${what} обрезан: показано ${n} из ${s.length} знаков]`;
AI.sleep = (ms, sig) => new Promise((ok, no) => { const t = setTimeout(ok, ms); sig?.addEventListener?.('abort', () => { clearTimeout(t); no(AI.aborted()) }, {once: true}) });
AI.uuid = () => '10000000-1000-4000-8000-100000000000'.replace(/[018]/g, c => (c ^ Math.random() * 16 >> c / 4).toString(16));
AI.id = p => (p || '') + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
AI.xesc = s => String(s ?? '').replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\uFFFE\uFFFF]/g, '').replace(/[<>&"]/g, c => ({'<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;'})[c]);
AI.xun = s => s.replace(/&(#x[\da-f]+|#\d+|lt|gt|amp|quot|apos);/gi, (m, e) => e[0] === '#'
  ? String.fromCodePoint(/x/i.test(e[1]) ? parseInt(e.slice(2), 16) : +e.slice(1)) : {lt: '<', gt: '>', amp: '&', quot: '"', apos: "'"}[e.toLowerCase()]);
/* loose — отдать прочитанное и при ошибке в хвосте */
AI.pipe = async (data, ts, loose) => {
  const w = ts.writable.getWriter(), r = ts.readable.getReader(), parts = [];
  w.write(data).catch(() => {}); w.close().catch(() => {});
  try { for (;;) { const {done, value} = await r.read(); if (done) break; parts.push(value) } } catch (e) { if (!loose || !parts.length) throw e }
  return AI.concat(parts);
};
AI.inflate = (b, fmt = 'deflate-raw', loose) => AI.pipe(AI.bytes(b), new DecompressionStream(fmt), loose);
AI.deflate = b => AI.pipe(AI.bytes(b), new CompressionStream('deflate-raw'));
/* Сеть: «запрос» приложения (подмена — AI.request) */
AI.send = async (url, o = {}) => {
  const req = AI.request || (typeof запрос === 'function' ? запрос : null), sig = o.signal;
  if (!req) throw AI.fail('net', 'Нет доступа к сети: приложение не передало функцию «запрос».');
  if (sig?.aborted) throw AI.aborted();
  let got = 0, r;
  const opt = {метод: o.method || 'GET', заголовки: o.headers || {}, срок: o.timeout || AI.timeout};
  if (o.body != null) opt.тело = typeof o.body === 'string' ? o.body : JSON.stringify(o.body);
  if (o.as) opt.вид = o.as;
  if (o.onChunk) opt.частями = c => { got++; o.onChunk(String(c)) };
  const pr = req(url, opt), stop = () => (pr.отменить || pr.cancel)?.call(pr);
  sig?.addEventListener?.('abort', stop);
  try { r = await pr } catch (e) {
    if (sig?.aborted || /отмен|cancel|abort/i.test(e?.message)) throw AI.aborted();
    throw AI.netError(e, o.p, url);
  } finally { sig?.removeEventListener?.('abort', stop) }
  if (sig?.aborted) throw AI.aborted();
  const res = {ok: r.ок ?? r.ok, status: r.код ?? r.status ?? 0, text: r.текст ?? r.text ?? '', json: r.тело ?? r.body ?? null, image: r.картинка, bytes: r.байты, streamed: got > 0};
  if (res.json == null && /^\s*[{[]/.test(res.text)) try { res.json = JSON.parse(res.text) } catch (e) {}
  if (!res.ok) throw res.status ? AI.httpError(o.p, o.s, res.status, res.text) : AI.netError(null, o.p, url);
  return res;
};
}

