  caps: C(/vl|qvq|omni|qwen3\.[5-9]/i), usage: true, images: 'qwen', imageModel: 'qwen-image', static: true, hosts: ['*.aliyuncs.com']});
P('qwen-local', 'Qwen локально (Ollama)', 'http://localhost:11434/v1', 'qwen3:8b', ['qwen3:8b', 'qwen3:14b', 'qwen3-vl:8b', 'qwen2.5-coder:7b'], {fields: [], list: 'ollama', usage: true, hosts: ['http://localhost:11434', 'http://127.0.0.1:11434'],
  cors: LOCAL + 'Ollama пускает страницы только с разрешённых адресов: задайте переменную окружения OLLAMA_ORIGINS=* (macOS — launchctl setenv, Linux — Environment в службе ollama) и перезапустите Ollama.'});
P('lmstudio', 'LM Studio (локально)', 'http://localhost:1234/v1', 'qwen/qwen3-8b', ['qwen/qwen3-8b', 'qwen/qwen3-14b', 'qwen/qwen2.5-vl-7b'], {fields: [], hosts: ['http://localhost:1234', 'http://127.0.0.1:1234'],
  cors: LOCAL + 'В LM Studio включите CORS: настройки сервера → «Enable CORS» (или «lms server start --cors»).'});
P('openrouter', 'OpenRouter', 'https://openrouter.ai/api/v1', 'qwen/qwen3-235b-a22b', ['qwen/qwen3-235b-a22b', 'qwen/qwen-plus', 'qwen/qwen2.5-vl-72b-instruct'], {
  caps: C(VISION, true), usage: true, images: 'openrouter', imageModel: 'google/gemini-2.5-flash-image', extra: () => Object.assign({'X-Title': AI.appTitle}, AI.site && {'HTTP-Referer': AI.site})});
const OAV = /gpt-4o|gpt-4\.1|gpt-5|\bo[134]/i;
P('openai', 'OpenAI', 'https://api.openai.com/v1', 'gpt-5-mini', ['gpt-5.5', 'gpt-5-mini', 'gpt-4.1'], {caps: C(OAV, OAV), usage: true, maxKey: 'max_completion_tokens', images: 'openai', imageModel: 'gpt-image-1'});
P('anthropic', 'Anthropic (Claude)', 'https://api.anthropic.com/v1', 'claude-sonnet-5-5', ['claude-opus-5-5', 'claude-sonnet-5-5', 'claude-haiku-4-5'], {kind: 'anthropic', auth: 'anthropic', caps: C(true, true)});
P('gemini', 'Gemini (Google)', 'https://generativelanguage.googleapis.com/v1beta', 'gemini-3.8-flash', ['gemini-3.8-flash', 'gemini-3.5-flash-lite', 'gemini-3.1-pro-preview'], {
  kind: 'gemini', auth: 'gemini', caps: C(true, true)});
P('yandex', 'YandexGPT (Yandex AI Studio)', 'https://ai.api.cloud.yandex.net/v1', 'yandexgpt-5.1', ['aliceai-llm', 'yandexgpt-5.1', 'qwen3-235b-a22b-fp8', 'qwen3.6-35b-a3b'], {
  auth: 'yandex', fields: ['apiKey', 'folderId'], urls: [['AI Studio', 'https://ai.api.cloud.yandex.net/v1'], ['Прежний адрес', 'https://llm.api.cloud.yandex.net/v1']], caps: C(/qwen3\.[6-9]|vl/i), static: true,
  hosts: ['ai.api.cloud.yandex.net', 'llm.api.cloud.yandex.net'], cors: 'Сервис, по имеющимся сведениям, не пускает запросы прямо из браузера (CORS): ' + GATE});
P('gigachat', 'GigaChat (Сбер)', 'https://gigachat.devices.sberbank.ru/api/v1', 'GigaChat-2-Max', ['GigaChat-2', 'GigaChat-2-Pro', 'GigaChat-2-Max'], {
  kind: 'giga', auth: 'giga', fields: ['authKey'], scopes: ['GIGACHAT_API_PERS', 'GIGACHAT_API_B2B', 'GIGACHAT_API_CORP'], authUrl: 'https://ngw.devices.sberbank.ru:9443/api/v2/oauth',
  urls: [['Основной', 'https://gigachat.devices.sberbank.ru/api/v1'], ['api.giga.chat', 'https://api.giga.chat/v1']], caps: C(false), hosts: ['gigachat.devices.sberbank.ru', 'api.giga.chat', 'ngw.devices.sberbank.ru:9443'],
  cors: 'Скорее всего, в системе нет корневого сертификата НУЦ Минцифры («Russian Trusted Root CA»): установите его с gosuslugi.ru/crt и перезапустите браузер. Не помогло — ' + GATE});
P('mistral', 'Mistral', 'https://api.mistral.ai/v1', 'mistral-medium-latest', ['mistral-large-latest', 'mistral-medium-latest', 'mistral-small-latest'], {toolName: true});
P('deepseek', 'DeepSeek', 'https://api.deepseek.com', 'deepseek-flash', ['deepseek-flash', 'deepseek-v4-pro', 'deepseek-chat'], {caps: C(false), usage: true});
P('custom', 'Свой адрес (совместимый сервис)', 'http://localhost:8000/v1', '', [], {optional: ['apiKey'], hosts: [],
  cors: 'Проверьте адрес и что сервис запущен; шлюз должен разрешать запросы страницы (CORS: Access-Control-Allow-Origin, заголовки Authorization и Content-Type).'});
AI.defaultProvider = 'qwen';
AI.provider = p => p && typeof p === 'object' ? p : AI.providers[p || AI.defaultProvider] || (() => { throw AI.fail('setup', `Неизвестное подключение «${p}».`) })();
/* Настройки человека поверх умолчаний */
AI.settings = (p, s = {}) => Object.assign({}, s, {url: String(s.url || p.url || '').trim().replace(/\/+$/, ''), model: String(s.model || p.model || '').trim()}, p.auth === 'giga' && {scope: s.scope || 'GIGACHAT_API_PERS'});
/* Умеет ли модель stream, tools, vision, pdf; явная настройка главнее */
AI.can = (p, s, cap) => { const v = s?.[cap] ?? p.caps[cap]; return v instanceof RegExp ? v.test(s?.model || p.model) : !!v };
AI.checkSetup = (p, s) => {
  const miss = ['url', 'model', ...p.fields].filter(f => !s[f] && !(p.optional || []).includes(f));
  if (miss.length) throw AI.fail('setup', `Для подключения «${p.name}» не заполнено: ${miss.map(f => AI.fieldNames[f]).join(', ')}.`);
};
/* Адреса для «сеть» в описании плагина */
AI.hosts = () => [...new Set(Object.values(AI.providers).flatMap(p => p.hosts))];
AI.headers = async (p, s, sig) => {
  const h = {'Content-Type': 'application/json'}, k = String(s.apiKey || '').trim(), a = p.auth;
  if (a === 'anthropic') Object.assign(h, {'x-api-key': k, 'anthropic-version': '2023-06-01', 'anthropic-dangerous-direct-browser-access': 'true'});
  else if (a === 'gemini') h['x-goog-api-key'] = k;
  else if (a === 'yandex') { h.Authorization = (/^t1\./.test(k) ? 'Bearer ' : 'Api-Key ') + k; if (s.folderId) h['OpenAI-Project'] = s.folderId }
  else if (a === 'giga') h.Authorization = 'Bearer ' + await gigaToken(p, s, sig);
  else if (k) h.Authorization = 'Bearer ' + k;
  return Object.assign(h, p.extra?.());
};
/* GigaChat: токен OAuth (RqUID — UUID) только в памяти */
const tokens = new Map();
const gigaToken = async (p, s, signal) => {
  const key = s.authKey + '|' + s.scope, t = tokens.get(key);
  if (t && t.exp - Date.now() > 60000) return t.token;
  const r = await AI.send(s.authUrl || p.authUrl, {method: 'POST', signal, p, s, body: 'scope=' + encodeURIComponent(s.scope),
    headers: {Authorization: 'Basic ' + String(s.authKey).trim().replace(/^Basic\s+/i, ''), RqUID: AI.uuid(), 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json'}});
  const j = r.json || {}, e = +j.expires_at || 0;
  if (!j.access_token) throw AI.fail('key', 'GigaChat не выдал токен доступа: ' + AI.clip(r.text, 200));
  tokens.set(key, {token: j.access_token, exp: e > 1e12 ? e : e > 1e9 ? e * 1000 : Date.now() + 29 * 60000});
  return j.access_token;
};
AI.forgetTokens = () => tokens.clear();
}

/* chat.js */
/* Разговор с моделью. Сообщение: {role: user|assistant|tool, text, images, files: [{name, mime, text|bytes}], toolCalls, toolCallId, name, error, thinking} */
{
const J = JSON.stringify;
AI.fileLimit = 60000;
const detail = t => {
  let j; try { j = JSON.parse(t) } catch (e) { return String(t || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 300) }
  const e = (Array.isArray(j) ? j[0] : j)?.error ?? j;
  return String((typeof e === 'string' ? e : e?.message || j.message || '') || '').slice(0, 300);
};
AI.httpError = (p, s, code, text) => {
  const d = detail(text), [kind, msg, tip] = {401: ['key', `${p?.auth === 'giga' ? 'ключ авторизации' : 'ключ доступа'} не принят`, 'проверьте его в настройках'],
    402: ['money', 'недостаточно средств на счёте'], 403: ['key', 'доступ запрещён', `проверьте ключ и права на модель «${s?.model}»`],
    404: ['model', `модель «${s?.model}» не найдена`, 'выберите другую или проверьте адрес'], 413: ['bad', 'запрос слишком большой', 'уберите часть вложений'],
    429: ['limit', 'превышен предел запросов или квота', 'подождите и повторите']}[code] || (code >= 500 || code === 408 ? ['server', 'сервис временно недоступен', 'повторите позже'] : ['bad', 'сервис отклонил запрос']);
  return AI.fail(kind, `${p ? `«${p.name}»: ` : ''}${msg} (код ${code})${tip ? ' — ' + tip : ''}${d ? ': ' + d : ''}.`, code, {detail: d});
};
AI.netError = (e, p, url) => {
  const n = p ? `«${p.name}»` : 'сервисом';
  return /не ответил|timeout|timed out|срок/i.test(e?.message) ? AI.fail('timeout', `${p ? n : 'Сервис'} не ответил вовремя — запрос прерван.`)
    : AI.fail('net', `Не удалось соединиться с ${n} (${String(url).split('/')[2] || url}). ${p?.cors || ''}`.trim(), 0, {detail: e?.message});
};
/* Поток: SSE (data: в несколько строк) и строки JSON */
AI.lines = onEvent => {
  let buf = '', data = [];
  const ev = d => { let j; try { j = JSON.parse(d) } catch (e) { return } r.n++; onEvent(j) };
  const flush = () => { const d = data.join('\n'); data = []; if (d && d.trim() !== '[DONE]') ev(d) };
  const line = l => {
    if (l.endsWith('\r')) l = l.slice(0, -1);
    if (!l) flush();
    else if (l.startsWith('data:')) {
      if (data.length) { let ok = 1; try { JSON.parse(data.join('\n')) } catch (e) { ok = 0 } if (ok) flush() }
      data.push(l.slice(5).replace(/^ /, ''));
    } else if (/^[{[]/.test(l)) { flush(); ev(l) }
  };
  const r = {n: 0, push(c) { buf += c; let i; while ((i = buf.indexOf('\n')) >= 0) { line(buf.slice(0, i)); buf = buf.slice(i + 1) } }, end() { if (buf) line(buf); buf = ''; flush() }};
  return r;
};
/* Видимый текст: без <think> и без JSON-вызова запасного протокола */
const CUT = /```(?:json)?\s*\{\s*"tool"|\{\s*"tool"\s*:/;
const emitter = (cb, cut) => {
  let all = '', sent = 0, think = '';
  const vis = () => {
    const t = all.trimStart();
    if (t.startsWith('<think>')) { const e = t.indexOf('</think>'); think = t.slice(7, e < 0 ? undefined : e).trim(); return e < 0 ? '' : t.slice(e + 8).trimStart() }
    return !t || '<think>'.startsWith(t) ? '' : all;
  };
  const out = (v, end) => { const m = cut ? v.search(CUT) : -1, lim = m >= 0 ? m : cut && !end ? v.length - 12 : v.length; if (lim > sent) { cb?.(v.slice(sent, lim), v.slice(0, lim)); sent = lim } return v };
  return {push(x) { if (x) { all += x; out(vis()) } }, think: () => think,
    done() { let v = vis(); if (!v && think && !all.includes('</think>')) { v = think; think = '' } return out(v, 1) }};
};
AI.parseToolText = text => {
  const calls = [], re = /\{\s*"tool"\s*:/g; let m, first = -1;
  while ((m = re.exec(text))) {
    let d = 0, q = false, k = m.index;
    for (; k < text.length; k++) { const c = text[k]; if (q) { if (c === '\\') k++; else if (c === '"') q = false } else if (c === '"') q = true; else if (c === '{') d++; else if (c === '}' && !--d) break }
    if (d) break;
    try { const j = JSON.parse(text.slice(m.index, k + 1)); if (typeof j.tool === 'string') { calls.push({id: AI.id('call_'), name: j.tool, args: j.args || j.arguments || {}}); if (first < 0) first = m.index } } catch (e) {}
    re.lastIndex = k + 1;
  }
  return first < 0 ? {text, calls} : {text: text.slice(0, first).replace(/```(?:json)?\s*$/, '').trim(), calls};
};
const args = a => { if (a && typeof a === 'object') return a; try { const v = JSON.parse(a || '{}'); return v && typeof v === 'object' ? v : {value: v} } catch (e) { return {_raw: a} } };
/* → общий вид (вложения текстом, картинки и PDF base64); без родных инструментов — всё текстом */
const prep = async (p, s, list, native) => {
  const vis = AI.can(p, s, 'vision'), pdf = AI.can(p, s, 'pdf'), out = [], names = {};
  for (const m of list) {
    const x = {role: m.role, text: String(m.text ?? ''), images: [], docs: [], calls: m.toolCalls || [], th: m.thinking || [], id: m.toolCallId, name: m.name || names[m.toolCallId], error: m.error};
    for (const t of x.calls) names[t.id] = t.name;
    for (const f of m.files || []) {
      if (f.text == null && f.bytes && pdf && /pdf/i.test((f.mime || '') + f.name)) { x.docs.push({name: f.name || 'документ.pdf', mime: 'application/pdf', data: AI.b64(f.bytes)}); continue }
      const r = f.text != null ? {text: AI.clip(f.text, AI.fileLimit, 'Текст вложения')} : await AI.extract(f);
      if (r.error) throw AI.fail('file', r.error);
      x.text += `\n\n--- Вложение «${f.name || 'файл'}» ---\n${r.text}\n--- конец вложения ---`;
