/* Диалоги: хранение, автоназвание, поиск; бюджет хранилища — вытеснением картинок и вложений, потом старых диалогов */
{
const GREET = /^\s*(привет\p{L}*|здравствуй\p{L}*|добр\p{L}+\s+(день|утро|вечер|утра|дня|вечера|ночи)|доброй ночи|хай|салют|hi|hello|hey)(?![\p{L}\d])[\s,!.)]*/iu;
