/* 00-app.js */
/* Плагин «ИИ»: связка ядра (AI) с приложением. Код выполняется в потоке плагина:
   доступны объекты приложения (книга/документ/проект/презентация), панель, окно,
   диалог, хранилище, запрос, файл, картинка, параметры, сообщить. */
const APP = typeof книга !== 'undefined' ? 'sheets' : typeof документ !== 'undefined' ? 'docs'
  : typeof проект !== 'undefined' ? 'projects' : typeof презентация !== 'undefined' ? 'slides' : 'sheets';
const APP_NAME = {sheets: 'Таблицы', docs: 'Документы', projects: 'Проекты', slides: 'Презентации'}[APP];
const CONTEXT_LIMIT = 24000, SELECTION_LIMIT = 16000;
const S = x => String(x == null ? '' : x);
const clip = (t, n, what) => AI.clip(t, n, what || 'Текст');
/* объект приложения и повод вызова */
const appObject = () => APP === 'sheets' ? книга : APP === 'docs' ? документ : APP === 'projects' ? проект : презентация;
const reason = () => { try { return appObject().повод || {}; } catch (e) { return {}; } };
/* текст из области значений: строки через перевод строки, клетки — табуляцией */
const tsv = rows => (rows || []).map(r => [].concat(r).map(v => v == null ? '' : typeof v === 'object' && v.e ? v.e : S(v)).join('\t')).join('\n');
const nonEmpty = rows => { let r2 = -1, c2 = -1; (rows || []).forEach((r, i) => [].concat(r).forEach((v, j) => { if (v !== null && v !== undefined && v !== '') { r2 = i; c2 = Math.max(c2, j) } }));
  return (rows || []).slice(0, r2 + 1).map(r => [].concat(r).slice(0, c2 + 1)) };
/* --- выделенное словами: что человек держит под курсором --- */
function selectedText(){
  try {
    if (APP === 'sheets') {
      const в = книга.выделение; if (!в) return '';
      const rows = nonEmpty(диапазон(в.область || в.адрес).значения);
      return rows.length === 1 && rows[0].length === 1 ? S(rows[0][0]) : clip(tsv(rows), SELECTION_LIMIT, 'Выделенное');
    }
    if (APP === 'docs') { const в = документ.выделение || {}; return S(в.текст || (в.блок >= 0 ? в.абзац : '')); }
    if (APP === 'projects') { const в = проект.выделение || {}, t = в.id != null ? проект.задача(в.id) : null;
      return t ? [t.имя, t.описание].filter(Boolean).join('\n') : ''; }
    const в = презентация.выделение || {};
    if (в.текст) return S(в.текст);
    const сл = (презентация.слайды || [])[(в.слайд || 1) - 1]; if (!сл) return '';
    const ф = в.фигура != null ? (сл.фигуры || []).find(x => x.id === в.фигура) : null;
    return S(ф ? ф.текст : сл.текст);
  } catch (e) { return ''; }
}
/* --- где человек: короткая строка для модели --- */
function whereText(){
  try {
    if (APP === 'sheets') { const в = книга.выделение || {}; return `Лист «${в.лист}», выделено ${в.область || в.адрес || '—'}.`; }
    if (APP === 'docs') { const в = документ.выделение || {}; return в.блок >= 0 ? `Курсор в блоке ${в.блок + 1} из ${в.блоков}${в.есть ? ', есть выделенный текст' : ''}.` : 'Курсор вне текста.'; }
    if (APP === 'projects') { const в = проект.выделение || {}; return в.имя ? `Выбрана задача ${в['№'] || ''} «${в.имя}».` : 'Задача не выбрана.'; }
    const в = презентация.выделение || {}; return `Слайд ${в.слайд || 1} из ${в.слайдов || (презентация.слайды || []).length}${в.фигура != null ? ', выбрана фигура' : ''}.`;
  } catch (e) { return ''; }
}
/* --- документ целиком (обрезан), по просьбе человека («с документом») --- */
async function documentText(){
  try {
    if (APP === 'sheets') {
      const parts = [];
      for (const имя of книга.листы.slice(0, 8)) {
        const л = лист(имя), rows = л.строк, cols = л.столбцов;
        if (!rows || !cols) { parts.push(`Лист «${имя}»: пусто`); continue; }
        const область = 'A1:' + colName(Math.min(cols, 40) - 1) + Math.min(rows, 60);
        const данные = nonEmpty(await л.прочитать(область));
        parts.push(`Лист «${имя}» (${rows} строк × ${cols} столбцов)${rows > 60 || cols > 40 ? ', начало' : ''}:\n${tsv(данные)}`);
      }
      return clip(parts.join('\n\n'), CONTEXT_LIMIT, 'Данные листов');
    }
    if (APP === 'docs') return clip(документ.текст, CONTEXT_LIMIT, 'Текст документа');
    if (APP === 'projects') {
      const t = проект.задачи || [];
      const lines = t.slice(0, 400).map(z => `${z['№'] || z.строка}${'  '.repeat(z.уровень || 0)} ${z.имя} | ${z.начало}–${z.окончание} | ${z.длительность} дн${z.трудоёмкость ? ' | ' + z.трудоёмкость + ' ч' : ''}${z.готово ? ' | ' + z.готово + '%' : ''}${(z.исполнители || []).length ? ' | ' + z.исполнители.join(', ') : ''}${z.веха ? ' | веха' : ''}${(z.связи || []).length ? ' | после ' + z.связи.map(с => с['№']).join(',') : ''}`);
      return clip(`Проект «${проект.имя}», ${проект.начало} — ${проект.конец}, задач ${t.length}${t.length > 400 ? ' (показаны первые 400)' : ''}:\n№ | имя | сроки | дни | часы | готово | исполнители | связи\n` + lines.join('\n'), CONTEXT_LIMIT, 'Список задач');
    }
    const сл = презентация.слайды || [];
    return clip(сл.map(с => `Слайд ${с.номер}. ${с.заголовок || ''}\n${с.текст || ''}${с.заметки ? '\nЗаметки: ' + с.заметки : ''}`).join('\n\n'), CONTEXT_LIMIT, 'Текст презентации');
  } catch (e) { return 'Содержимое не прочитано: ' + e.message; }
}
const colName = n => { let s = ''; n++; while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };
const A1 = (r, c) => colName(c) + (r + 1);
/* --- простая разметка ответа → HTML для документа --- */
const esc = t => S(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const inline = t => esc(t).replace(/`([^`]+)`/g, '<code>$1</code>').replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>').replace(/(^|[\s(])\*([^*]+)\*/g, '$1<i>$2</i>');
function mdToHtml(text){
  const L = S(text).replace(/\r/g, '').split('\n'), out = []; let list = null, para = [], table = null, code = null;
  const fp = () => { if (para.length) { out.push('<p>' + para.map(inline).join(' ') + '</p>'); para = []; } };
  const fl = () => { if (list) { out.push(list.h + '</' + list.t + '>'); list = null; } };
  const ft = () => { if (table) { out.push('<table>' + table.join('') + '</table>'); table = null; } };
  for (const l of L) {
    if (code) { if (/^\s*```/.test(l)) { out.push('<pre>' + esc(code.join('\n')) + '</pre>'); code = null; } else code.push(l); continue; }
    if (/^\s*```/.test(l)) { fp(); fl(); ft(); code = []; continue; }
    if (!l.trim()) { fp(); fl(); ft(); continue; }
    const t = /^\s*\|(.*)\|\s*$/.exec(l);
    if (t) { fp(); fl(); if (/^[\s|:-]+$/.test(l)) continue; const tag = table ? 'td' : 'th'; (table = table || []).push('<tr>' + t[1].split('|').map(x => `<${tag}>${inline(x.trim())}</${tag}>`).join('') + '</tr>'); continue; }
    ft();
    const h = /^\s*(#{1,4})\s+(.*)$/.exec(l);
    if (h) { fp(); fl(); const n = Math.min(3, h[1].length + 1); out.push(`<h${n}>${inline(h[2])}</h${n}>`); continue; }
    const b = /^\s*([-*•]|\d+[.)])\s+(.*)$/.exec(l);
    if (b) { fp(); const tg = /^\d/.test(b[1]) ? 'ol' : 'ul'; if (!list || list.t !== tg) { fl(); list = {t: tg, h: '<' + tg + '>'}; } list.h += '<li>' + inline(b[2]) + '</li>'; continue; }
    fl(); para.push(l.trim());
  }
  if (code) out.push('<pre>' + esc(code.join('\n')) + '</pre>');
  fp(); fl(); ft();
  return out.join('');
}
/* таблица из ответа: markdown-таблица или строки с табуляцией → массив массивов */
function tableOf(text){
  const L = S(text).replace(/\r/g, '').split('\n').filter(l => l.trim());
  const md = L.filter(l => /^\s*\|.*\|\s*$/.test(l));
  if (md.length >= 2 && md.length >= L.length - 1) return md.filter(l => !/^[\s|:-]+$/.test(l)).map(l => l.replace(/^\s*\||\|\s*$/g, '').split('|').map(x => cellValue(x.trim())));
  if (L.length && L.every(l => l.includes('\t'))) return L.map(l => l.split('\t').map(x => cellValue(x.trim())));
  return null;
}
const cellValue = x => { const n = x.replace(/\s/g, '').replace(',', '.'); return /^[-+]?\d+(\.\d+)?$/.test(n) && n !== '' ? +n : x.replace(/\*\*/g, ''); };
/* --- вставить ответ туда, где человек --- */
async function insertAnswer(text){
  text = S(text).trim();
  if (!text) return 'Вставлять нечего';
  if (APP === 'docs') { await документ.вставитьВКурсор(/^[#>*\-|`\d]|\n\s*[-*]\s|\*\*/.test(text) ? mdToHtml(text) : text); return 'Вставлено в документ'; }
  if (APP === 'slides') { await презентация.вставитьТекст(text.replace(/\*\*|`/g, '')); return 'Вставлено на слайд'; }
  if (APP === 'projects') {
    const в = проект.выделение || {};
    if (в.id == null) return 'Выберите задачу — текст станет её описанием';
    проект.правитьЗадачу(в.id, {описание: text}); return `Описание задачи «${в.имя}» заменено`;
  }
  const в = книга.выделение; if (!в) return 'Нет выделенной клетки';
  const адрес = в.адрес || A1(в.строка, в.столбец);
  if (/^=/.test(text) && !text.includes('\n')) { ячейка(адрес).формула = text.slice(1).trim(); return `Формула записана в ${адрес}`; }
  const table = tableOf(text);
  if (table) { диапазон(адрес).записать(table); return `Таблица ${table.length}×${table[0].length} записана с ${адрес}`; }
  const lines = text.split('\n').map(l => l.replace(/^\s*[-*•]\s+|\*\*/g, '').trimEnd()).filter(l => l !== '');
  if (lines.length > 1) { диапазон(адрес).записать(lines.map(l => [cellValue(l)])); return `${lines.length} строк записано с ${адрес}`; }
  ячейка(адрес).значение = cellValue(lines[0] || ''); return `Записано в ${адрес}`;
}

/* 10-settings.js */
/* --- подключения: настройки человека в хранилище плагина (не в книге) ---
   ии.подключение — id активного; ии.н.<id> — {url, model, folderId, scope, maxTokens, temperature, imageModel};
   ключи доступа — тайно: ии.к.<id>. Панель держит скрытые поля «адрес» и «хост»:
