function activeId(){ const id = хранилище.взять('ии.подключение', '') || AI.defaultProvider; return AI.providers[id] ? id : AI.defaultProvider; }
function savedSettings(id){ const s = хранилище.взять('ии.н.' + id, null); return s && typeof s === 'object' ? Object.assign({}, s) : {}; }
function connection(id){
