/* сообщения диалога → лента чата */
/* «shown» — что показать вместо длинной просьбы (действия с ленты: «Объяснить: «…»») */
const toChat = t => (t.messages || []).filter(m => m.role !== 'tool').map(m => ({роль: m.role === 'user' ? 'я' : m.role === 'system' ? 'служба' : 'ии', текст: m.shown || m.text || '',
  картинки: m.images || [], вложения: (m.files || []).map(f => f.name), ход: m.steps || [], ошибка: !!m.error}));
