function ПоказатьЧат(){ syncNetFields(); showThread(); }
function НовыйДиалог(){
  const cur = currentThread();
  if (!(cur.messages || []).length) { showThread(); return; }     // текущий и так пуст — второго пустого не заводим
  const t = threads.create({provider: activeId()}); currentId = t.id; хранилище.положить('ии.текущий', currentId); showThread();
}
/* куски ответа — в чат не чаще раза в 80 мс */
function streamer(){
  let buf = '', timer = null;
  const flush = () => { timer = null; if (buf) { панель.чат(CHAT, {дописать: buf}); buf = ''; } };
  return {push(c){ buf += c; if (!timer) timer = setTimeout(flush, 80); }, end(){ if (timer) clearTimeout(timer); flush(); }};
}
/* история для модели: последние сообщения в бюджете знаков */
function history(t, budget = 60000){
  const out = []; let n = 0;
  for (let i = t.messages.length - 1; i >= 0; i--) {
    const m = t.messages[i]; if (m.role === 'system') continue;
    n += (m.text || '').length + (m.files || []).reduce((a, f) => a + (f.text || '').length, 0) + (m.images || []).length * 2000;
    if (n > budget && out.length) break;
    out.unshift({role: m.role, text: m.text || '', images: m.images, files: m.files, toolCalls: m.toolCalls, toolCallId: m.toolCallId, name: m.name});
  }
  while (out.length && out[0].role !== 'user') out.shift();
  return out;
}
/* Документ уходит сервису только по флажку «Открытый документ — в контексте разговора» (по умолчанию
