let toldContext = false;
async function systemPrompt(withDoc){
  const parts = [whereText()];
  if (withDoc) {
    const d = await documentText();
    if (d) {
      const what = ({sheets: 'файла (листы)', docs: 'документа', projects: 'плана', slides: 'набора слайдов'})[APP];
      parts.push('Содержимое открытого ' + what + ':\n"""\n' + d + '\n"""');
      сообщить('С вопросом уходит содержимое открытого ' + what + ': ' + d.length.toLocaleString('ru-RU') + ' зн. (флажок «Открытый документ — в контексте разговора»)');
      if (!toldContext) { toldContext = true; try { панель.сообщение('Сервису ИИ уходит и содержимое открытого файла (' + d.length.toLocaleString('ru-RU') + ' зн.) — так задано флажком «Открытый документ — в контексте разговора».'); } catch (e) {} }
    }
  }
  return AI.system(APP, {extra: parts.filter(Boolean).join('\n\n')});
}
async function attachments(list){
  const out = [];
  for (const f of list || []) {
    const r = await AI.extract({name: f.имя, mime: f.тип, bytes: f.байты});
    if (r.error) { сообщить(r.error); out.push({name: f.имя, mime: f.тип, text: r.error}); }
    else out.push({name: f.имя, mime: f.тип, text: r.text});
  }
  return out;
}
/* ответ модели в текущий диалог; user уже добавлен в t и в чат */
async function answer(t, o = {}){
  const {p, s} = connection();
  running = new AbortController();
  const msg = {роль: 'ии', текст: '', идёт: true};
  панель.чат(CHAT, {добавить: msg});
  const st = streamer();
  try {
    const r = await AI.chat({provider: p, settings: s, system: await systemPrompt(!!параметры().контекст), messages: history(t), signal: running.signal,
      onDelta: c => st.push(c)});
    st.end();
    let text = r.text || '';
    if (r.images?.length && APP !== 'projects') text += (text ? '\n\n' : '') + '(картинка получена — вставлена в документ)';
    if (r.finish === 'length') text += '\n\n…ответ обрезан по пределу длины модели.';
    if (r.finish === 'filter') text += '\n\n(ответ остановлен фильтром сервиса)';
    threads.add(t.id, {role: 'assistant', text, images: r.images?.length ? r.images : undefined});
    панель.чат(CHAT, {сообщения: toChat(t)});
    if (r.images?.length) for (const im of r.images) await putImage(im);
    return text;
  } catch (e) {
    st.end();
    const text = (e.partial ? e.partial + '\n\n' : '') + (e.kind === 'abort' ? 'Остановлено.' : 'Ошибка: ' + e.message);
    threads.add(t.id, {role: 'assistant', text, error: e.kind !== 'abort'});
    панель.чат(CHAT, {сообщения: toChat(t)});
    return null;
  } finally { running = null; }
}
/* «Отправить» в панели */
async function Спросить(){
  const п = параметры(), ч = п.чат || {};
