  if (!text && !images.length && !files.length) return;
  const t = currentThread();
  const {p, s} = connection();
  if (images.length && !AI.can(p, s, 'vision')) { сообщить(`Модель «${s.model}» (${p.name}) картинок не принимает — выберите модель со зрением.`); }
  threads.add(t.id, {role: 'user', text: text || (images.length ? 'Что на картинке?' : 'Что в файле?'), images, files});
  панель.чат(CHAT, {сообщения: toChat(t)});
