    T('add_slide', 'Добавить слайд «заголовок и текст» после слайда after (номер; 0 — в начало, пусто — в конец).', {after: num('после какого'), title: str('заголовок'), bullets: {type: 'array', items: {}, description: 'пункты: строки или {text, level}'}, notes: str('заметки докладчика')}, ['title'],
      async a => ({номер: презентация.добавитьСлайд(a.after == null ? undefined : +a.after, {заголовок: need(a, 'title'), пункты: (a.bullets || []).map(b => typeof b === 'string' ? b : {текст: b.text, уровень: b.level || 0}), заметки: a.notes || ''})})),
    T('edit_shape', 'Заменить текст фигуры слайда.', {slide: num('номер слайда'), id: str('id фигуры'), text: str('новый текст')}, ['slide', 'id', 'text'], async a => { презентация.правитьФигуру(+need(a, 'slide'), need(a, 'id'), {текст: need(a, 'text')}); return 'изменено'; }),
    T('edit_slide', 'Изменить заголовок или заметки слайда.', {slide: num('номер'), title: str(''), notes: str('')}, ['slide'], async a => { const f = {}; if (a.title != null) f.заголовок = a.title; if (a.notes != null) f.заметки = a.notes; презентация.правитьСлайд(+need(a, 'slide'), f); return 'изменено'; }),
    T('remove_slide', 'Удалить слайд.', {slide: num('номер')}, ['slide'], async a => { презентация.удалитьСлайд(+need(a, 'slide')); return 'удалён слайд ' + a.slide; }),
    T('go', 'Показать слайд человеку.', {slide: num('номер')}, ['slide'], async a => { презентация.перейти(+need(a, 'slide')); return 'показано'; }),
  ];
}
function ОткрытьАгента(){ окно.открыть('агент', {задача: '', шагов: 12}); }
async function ЗапуститьАгента(){
  const п = параметры(), task = S(п.задача).trim(); if (!task) return;
  await runAgent(task, +п.шагов || 12);
}
async function runAgent(task, maxSteps){
  const t = currentThread(), {p, s} = connection();
  threads.add(t.id, {role: 'user', text: task, shown: 'Агент: ' + task});
  панель.чат(CHAT, {сообщения: toChat(t)});
  панель.чат(CHAT, {добавить: {роль: 'ии', текст: '', идёт: true, ход: []}});
  const steps = [], st = streamer();
  running = new AbortController();
  try {
    const r = await AI.runAgent({provider: p, settings: s, system: await systemPrompt(false), messages: history(t), tools: toolsFor(), maxSteps, signal: running.signal,
      onStep: x => { const line = {вид: x.kind, текст: x.kind === 'tool' ? `${x.name}(${x.summary || ''})${x.done ? ' ✓' : ''}` : x.summary || ''}; steps.push(line); панель.чат(CHAT, {шаг: line}); },
      onDelta: (c, all) => {}});
    threads.add(t.id, {role: 'assistant', text: r.text, steps});
  } catch (e) {
    threads.add(t.id, {role: 'assistant', text: e.kind === 'abort' ? 'Остановлено.' : 'Ошибка: ' + e.message, steps, error: e.kind !== 'abort'});
  } finally { running = null; st.end(); }
  панель.чат(CHAT, {сообщения: toChat(t)});
}
