async function СоставитьПлан(){
  const п = параметры(), topic = S(п.тема).trim(); if (!topic) return;
  const t = currentThread();
  threads.add(t.id, {role: 'user', text: `Составь план презентации на ${+п.слайдов || 8} слайдов по теме:\n"""\n${topic}\n"""\n\n${AI.outlineFormat}`, shown: 'План слайдов: ' + clip(topic.replace(/\s+/g, ' '), 100, '')});
  панель.чат(CHAT, {сообщения: toChat(t)});
  const text = await answer(t);
  if (text && APP === 'slides') сообщить('План готов — под ответом нажмите «Создать слайды».');
}
async function СоздатьСлайды(){
  const ч = параметры().чат || {}, plan = AI.parseOutline(ч.текст);
  if (!plan.length) { сообщить('В этом ответе плана слайдов не видно (нужны строки «# Заголовок» и пункты «- …»).'); return; }
  if (APP === 'slides') {
    let after = (презентация.выделение || {}).слайд || (презентация.слайды || []).length;
    for (const s of plan) after = презентация.добавитьСлайд(after, {заголовок: s.title, пункты: s.bullets.map(b => ({текст: b.text, уровень: b.level})), заметки: s.notes});
    презентация.перейти(after);
    сообщить(`Создано слайдов: ${plan.length}`); return;
  }
  if (APP === 'docs') { await документ.вставитьВКурсор(plan.map(s => `<h2>${esc(s.title)}</h2>${s.bullets.length ? '<ul>' + s.bullets.map(b => '<li>' + esc(b.text) + '</li>').join('') + '</ul>' : ''}`).join('')); сообщить('Разделы вставлены'); return; }
  if (APP === 'projects') { let after; const sel = проект.выделение || {}; after = sel.id != null ? sel.id : undefined;
    for (const s of plan) { const id = проект.добавитьЗадачу(after, {имя: s.title, описание: s.notes || ''}); for (const b of s.bullets) проект.добавитьЗадачу(id, {имя: b.text, уровень: 1}); after = id; }
    await проект.пересчитать(); сообщить(`Добавлено задач: ${plan.reduce((a, s) => a + 1 + s.bullets.length, 0)}`); return; }
  сообщить(await insertAnswer(plan.map(s => [s.title, ...s.bullets.map(b => '  '.repeat(b.level) + '- ' + b.text)].join('\n')).join('\n')));
}
/* --- картинки --- */
async function putImage(dataUrl){
  try {
    if (APP === 'sheets') { const в = книга.выделение || {}; картинка.вставить(dataUrl, {адрес: в.адрес || 'A1'}); return 'Картинка на листе'; }
    if (APP === 'docs') { документ.объект(dataUrl, {плагин: 'ии'}, {ширина: 400, высота: 300}); return 'Картинка в документе'; }
    if (APP === 'slides') { await презентация.вставитьКартинку(dataUrl, {}); return 'Картинка на слайде'; }
    return 'Картинка показана в чате';
  } catch (e) { return 'Картинка не вставлена: ' + e.message; }
}
