  панель.чат(CHAT, {добавить: {роль: 'ии', текст: 'Рисую…', идёт: true}});
  running = new AbortController();
  try {
    const im = await AI.makeImage({provider: p, settings: s, prompt, aspect: {квадрат: 'square', широкая: 'wide', высокая: 'tall'}[п.форма] || 'square', signal: running.signal});
    const where = await putImage(im);
    threads.add(t.id, {role: 'assistant', text: where, images: [im]});
  } catch (e) { threads.add(t.id, {role: 'assistant', text: e.kind === 'abort' ? 'Остановлено.' : 'Ошибка: ' + e.message, error: e.kind !== 'abort'}); }
  finally { running = null; }
  панель.чат(CHAT, {сообщения: toChat(t)});
}

/* 40-cells.js */
/* --- ИИ-функции клеток (Таблицы) — поле «формулы» описания плагина ---
   =ИИ.СПРОСИТЬ("вопрос"; A1:B9)   =ИИ.ПЕРЕВЕСТИ(A1; "английский")   =ИИ.ИЗВЛЕЧЬ(A1; "сумма")
   =ИИ.КЛАСС(A1; "жалоба;вопрос;спасибо")   =ИИ.КРАТКО(A1)
   Считаются здесь, в живом потоке плагина, с его подключением; ответ — одно
   значение клетки (AI.cellValue), сбой — ошибка с причиной в подсказке клетки.
   Приложение само запоминает ответы в книге по паре «функция + доводы» и не
   спрашивает дважды одно и то же. */
const CELL_LIMIT = 6000;
const cellText = v => Array.isArray(v) ? tsv(nonEmpty(v)) : S(v);
const cellList = v => Array.isArray(v) ? nonEmpty(v).flat().map(S).map(x => x.trim()).filter(Boolean) : S(v).split(/[;,\n|]/).map(x => x.trim()).filter(Boolean);
async function cellAsk(question, data){
  const {p, s} = connection();
  AI.checkSetup(p, s);
  const r = await AI.chat({provider: p, settings: Object.assign({}, s, {temperature: 0}), system: AI.system('sheets', {cell: true}), stream: false,
    messages: [{role: 'user', text: AI.cellMessage(question, data == null ? '' : clip(cellText(data), CELL_LIMIT, 'Данные'))}]});
  const v = AI.cellValue(r.text);
  if (v && typeof v === 'object' && v.e) throw new Error('модель не нашла ответа');
  return v;
}
function ИиСпросить(вопрос, данные){
  const q = S(вопрос).trim(); if (!q) throw new Error('нужен вопрос');
  return cellAsk(q, данные);
}
function ИиПеревести(текст, язык){
  const t = cellText(текст).trim(); if (!t) return '';
  return cellAsk(`Переведи на ${S(язык).trim() || 'английский'} язык, верни только перевод:\n"""\n${clip(t, CELL_LIMIT)}\n"""`);
}
function ИиИзвлечь(текст, что){
  const t = cellText(текст).trim(); if (!t) return '';
  const w = S(что).trim(); if (!w) throw new Error('скажите, что извлечь: ИИ.ИЗВЛЕЧЬ(текст; "дата")');
  return cellAsk(`Из текста извлеки: ${w}. Верни только найденное значение, нет такого — #Н/Д.\n"""\n${clip(t, CELL_LIMIT)}\n"""`);
}
async function ИиКласс(текст, категории){
  const t = cellText(текст).trim(); if (!t) return '';
  const list = cellList(категории); if (!list.length) throw new Error('нужен список категорий: ИИ.КЛАСС(текст; "да;нет")');
  const v = await cellAsk(`Отнеси текст к одной из категорий: ${list.join('; ')}. Верни только название категории из списка.\n"""\n${clip(t, CELL_LIMIT)}\n"""`);
  const got = S(v).trim().toLowerCase();
  return list.find(x => x.toLowerCase() === got) || list.find(x => got.includes(x.toLowerCase()) || x.toLowerCase().includes(got)) || S(v);
}
function ИиКратко(текст, слов){
  const t = cellText(текст).trim(); if (!t) return '';
  return cellAsk(`Перескажи текст одним предложением${+слов > 0 ? ' до ' + Math.round(+слов) + ' слов' : ''}, на его языке, без вступлений:\n"""\n${clip(t, CELL_LIMIT)}\n"""`);
}
